const owner = 'SaZix-T';
const repo = 'ITMOv2';
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const pad = function (n) { return (n < 10 ? '0' : '') + n; };
const iso = function (d) {
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) +
    'T' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds()) + 'Z';
};
const day = function (d) {
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
};
return [{ json: {
  owner: owner,
  repo: repo,
  since: iso(since),
  until: iso(now),
  weekStart: day(since),
  weekEnd: day(now),
  weekLabel: day(since) + ' — ' + day(now),
}}];

const week = $('Compute Week Window').first().json;
const since = new Date(week.since).getTime();
const until = new Date(week.until).getTime();
const pad = function (n) { return (n < 10 ? '0' : '') + n; };
const day = function (d) {
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
};

const openedRes = $('GH: Issues Created').all();
const closedRes = $('GH: Issues Closed').all();
const commentsRes = $('GH: Issue Comments').all();
const pullsRes = $('GH: Pull Requests').all();

const list = function (items) {
  if (!items.length) return [];
  const first = items[0].json;
  if (Array.isArray(first)) return first;
  if (first && Array.isArray(first.data)) return first.data;
  if (first && first.items && Array.isArray(first.items.data)) return first.items.data;
  return items.map(function (i) { return i.json; });
};

const issuesOpened = list(openedRes).filter(function (i) {
  if (!i || i.pull_request || !i.created_at) return false;
  const t = new Date(i.created_at).getTime();
  return t >= since && t <= until;
});

const issuesClosed = list(closedRes).filter(function (i) {
  if (!i || i.pull_request || !i.closed_at) return false;
  const t = new Date(i.closed_at).getTime();
  return t >= since && t <= until;
});

const comments = list(commentsRes).filter(function (c) {
  if (!c || !c.created_at) return false;
  const t = new Date(c.created_at).getTime();
  return t >= since && t <= until;
});

const pulls = list(pullsRes).filter(function (p) {
  if (!p || !p.updated_at) return false;
  const t = new Date(p.updated_at).getTime();
  return t >= since && t <= until;
});

const typeOf = function (issue) {
  const labels = (issue.labels || []).map(function (l) { return (typeof l === 'string') ? l : l.name; });
  const known = ['bug', 'task', 'feature'];
  for (const k of known) {
    if (labels.includes(k)) return k;
  }
  if (labels.includes('needs-triage')) return 'needs-triage';
  return 'без метки';
};

const byType = {};
const byAuthor = {};
const bump = function (obj, key, opened, closed, commentsCount) {
  if (!obj[key]) obj[key] = { name: key, opened: 0, closed: 0, comments: 0, total: 0 };
  obj[key].opened += opened;
  obj[key].closed += closed;
  obj[key].comments += commentsCount;
  obj[key].total += opened + closed;
};

for (const i of issuesOpened) bump(byType, typeOf(i), 1, 0, 0);
for (const i of issuesClosed) bump(byType, typeOf(i), 0, 1, 0);
for (const i of issuesOpened) bump(byAuthor, (i.user && i.user.login) || 'unknown', 1, 0, 0);
for (const i of issuesClosed) bump(byAuthor, (i.user && i.user.login) || 'unknown', 0, 1, 0);

const commentAuthors = {};
for (const c of comments) {
  const login = (c.user && c.user.login) || 'unknown';
  commentAuthors[login] = (commentAuthors[login] || 0) + 1;
}
for (const login of Object.keys(commentAuthors)) {
  if (!byAuthor[login]) byAuthor[login] = { name: login, opened: 0, closed: 0, comments: 0, total: 0 };
  byAuthor[login].comments += commentAuthors[login];
}

const sortRows = function (obj) {
  return Object.keys(obj).map(function (k) { return obj[k]; })
    .sort(function (a, b) { return b.total - a.total || b.comments - a.comments; });
};

const opened = issuesOpened.length;
const closed = issuesClosed.length;
const commentsCount = comments.length;
const pullsCount = pulls.length;

return [{ json: {
  weekStart: week.weekStart,
  weekEnd: week.weekEnd,
  weekLabel: week.weekLabel,
  opened: opened,
  closed: closed,
  comments: commentsCount,
  pulls: pullsCount,
  byType: sortRows(byType),
  byAuthor: sortRows(byAuthor),
  byTypeJson: JSON.stringify(sortRows(byType)),
  byAuthorJson: JSON.stringify(sortRows(byAuthor)),
}}];

const stats = $('Aggregate Stats').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.week_start; });

let prev = null;
for (const r of rows) {
  if (r.week_start === stats.weekStart) continue;
  if (r.week_start > stats.weekStart) continue;
  if (!prev || r.week_start > prev.week_start) prev = r;
}

const num = function (v) { return Number(v || 0); };
const delta = function (cur, before) {
  if (before === null || before === undefined) return null;
  return num(cur) - num(before);
};
const fmtDelta = function (d) {
  if (d === null) return '—';
  if (d > 0) return '+' + d;
  return String(d);
};
const tone = function (d) {
  if (d === null) return '#6b7280';
  if (d > 0) return '#dc2626';
  if (d < 0) return '#16a34a';
  return '#6b7280';
};

const dOpened = prev ? delta(stats.opened, prev.opened) : null;
const dClosed = prev ? delta(stats.closed, prev.closed) : null;
const prevComments = prev ? (prev.comment_count !== undefined ? prev.comment_count : prev.comments) : null;
const dComments = prev ? delta(stats.comments, prevComments) : null;
const dPulls = prev ? delta(stats.pulls, prev.pulls) : null;

const mk = function (v, d) {
  return '<td>' + v + '</td><td style="color:' + tone(d) + ';white-space:nowrap">' + fmtDelta(d) + '</td>';
};

let typeRows = '';
for (const t of stats.byType) {
  const before = prev && Array.isArray(prev.byType) ? prev.byType : [];
  const old = before.filter(function (x) { return x.name === t.name; })[0];
  const dt = old ? (t.total - old.total) : null;
  typeRows += '<tr><td>' + t.name + '</td><td>' + t.opened + '</td><td>' + t.closed + '</td><td>' + t.comments + '</td>' + mk(t.total, dt) + '</tr>';
}
if (!typeRows) typeRows = '<tr><td colspan="5">за неделю нет активности</td></tr>';

let authorRows = '';
for (const a of stats.byAuthor) {
  const before = prev && Array.isArray(prev.byAuthor) ? prev.byAuthor : [];
  const old = before.filter(function (x) { return x.name === a.name; })[0];
  const dt = old ? (a.total - old.total) : null;
  authorRows += '<tr><td>' + a.name + '</td><td>' + a.opened + '</td><td>' + a.closed + '</td><td>' + a.comments + '</td>' + mk(a.total, dt) + '</tr>';
}
if (!authorRows) authorRows = '<tr><td colspan="5">за неделю нет активности</td></tr>';

const th = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #d1d5db;font-size:13px"';
const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e7eb;font-size:13px"';

const htmlBody = [
  '<div style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#111827">',
  '<h2 style="margin:0 0 4px">Еженедельная статистика Issues</h2>',
  '<p style="margin:0 0 16px;color:#6b7280">Неделя: ' + stats.weekLabel + ' · репозиторий SaZix-T/ITMOv2</p>',
  '<table style="border-collapse:collapse;margin-bottom:8px">',
  '<tr><th ' + th + '>Показатель</th><th ' + th + '>За неделю</th><th ' + th + '>Δ к прошлой</th></tr>',
  '<tr><td ' + td + '>Открыто Issues</td>' + mk(stats.opened, dOpened) + '</tr>',
  '<tr><td ' + td + '>Закрыто Issues</td>' + mk(stats.closed, dClosed) + '</tr>',
  '<tr><td ' + td + '>Комментариев</td>' + mk(stats.comments, dComments) + '</tr>',
  '<tr><td ' + td + '>Активных PR</td>' + mk(stats.pulls, dPulls) + '</tr>',
  '</table>',
  '<p style="margin:0 0 6px;color:#6b7280;font-size:12px">',
  prev ? ('Сравнение с неделей ' + prev.week_start) : 'Прошлой недели в Data Table нет — Δ не рассчитан',
  '</p>',
  '<h3 style="margin:18px 0 6px">По типам</h3>',
  '<table style="border-collapse:collapse;width:100%">',
  '<tr><th ' + th + '>Тип</th><th ' + th + '>Открыто</th><th ' + th + '>Закрыто</th><th ' + th + '>Комментарии</th><th ' + th + '>Δ</th></tr>',
  typeRows,
  '</table>',
  '<h3 style="margin:18px 0 6px">По авторам</h3>',
  '<table style="border-collapse:collapse;width:100%">',
  '<tr><th ' + th + '>Автор</th><th ' + th + '>Открыто</th><th ' + th + '>Закрыто</th><th ' + th + '>Комментарии</th><th ' + th + '>Δ</th></tr>',
  authorRows,
  '</table>',
  '<!--ANNOTATION-->',
  '</div>',
].join('');

const prompt = [
  'Ты аналитик учебного проекта. Ниже статистика GitHub Issues за неделю и изменение к прошлой неделе.',
  '',
  'Неделя: ' + stats.weekLabel,
  'Открыто Issues: ' + stats.opened + ' (Δ ' + fmtDelta(dOpened) + ')',
  'Закрыто Issues: ' + stats.closed + ' (Δ ' + fmtDelta(dClosed) + ')',
  'Комментариев: ' + stats.comments + ' (Δ ' + fmtDelta(dComments) + ')',
  'Активных PR: ' + stats.pulls + ' (Δ ' + fmtDelta(dPulls) + ')',
  '',
  'По типам: ' + (stats.byType.map(function (t) { return t.name + ': открыто ' + t.opened + ', закрыто ' + t.closed; }).join('; ') || 'нет данных'),
  'По авторам: ' + (stats.byAuthor.map(function (a) { return a.name + ': ' + a.total + ' событий'; }).join('; ') || 'нет данных'),
  '',
  'Напиши по-русски 3-4 предложения: что изменилось к прошлой неделе, на что обратить внимание команде.',
  'Без заголовков и markdown-разметки, обычный текст.',
].join(String.fromCharCode(10));

return [{ json: {
  weekStart: stats.weekStart,
  weekEnd: stats.weekEnd,
  weekLabel: stats.weekLabel,
  opened: stats.opened,
  closed: stats.closed,
  comments: stats.comments,
  pulls: stats.pulls,
  byTypeJson: stats.byTypeJson,
  byAuthorJson: stats.byAuthorJson,
  htmlBody: htmlBody,
  prompt: prompt,
  prevWeek: prev ? prev.week_start : '',
  deltaOpened: dOpened === null ? '' : dOpened,
  deltaClosed: dClosed === null ? '' : dClosed,
  deltaComments: dComments === null ? '' : dComments,
  deltaPulls: dPulls === null ? '' : dPulls,
}}];
